package calc

import (
	"fmt"
	"math"
)

// 0x4fb4c0 spell_cast_resolve(spell, src, tgt, level, bonus, fail, keep, out,
// mode, list2, list1) and its cycle partners 0x54ba00 (effect dispatch),
// 0x54c930 (reflection) and 0x4fa4d0 (character cast). All members share one
// fixture world (spcWorld; re/emu/cases/004fb4c0.json). 排除 callees and the
// 0x54ba00 effect handlers are address stubs; small rule helpers run natively.

const (
	spcLocal     = 0x7e800000 // fixture stack region for the members' locals
	spcLocalSize = 0x10000
)

type spcWorld struct {
	*mcaWorld
	loc uint32
}

func spcPanic(s string) { panic("spell cast: " + s) }

func (w *spcWorld) local(n uint32) uint32 {
	n = (n + 3) &^ 3
	if w.loc+n > spcLocalSize {
		spcPanic("locals past the fixture stack region")
	}
	a := spcLocal + w.loc
	w.loc += n
	return a
}

// Match the emulator's allocation arena for nested spell effects.
func (w *spcWorld) alloc(n uint32) uint32 {
	sz := (n + 7) &^ 7
	if sz < 8 {
		sz = 8
	}
	if sz > 0x100000 || w.heap > 0x100000-sz {
		spcPanic("heap allocations past the fixture window")
	}
	a := mstHeap + w.heap
	w.heap += sz
	return a
}

func (w *spcWorld) f32(a uint32) float32     { return math.Float32frombits(w.u32(a)) }
func (w *spcWorld) putF(a uint32, v float32) { w.put(a, 4, uint64(math.Float32bits(v))) }
func (w *spcWorld) put8(a uint32, v byte)    { w.put(a, 1, uint64(v)) }
func (w *spcWorld) put32(a, v uint32)        { w.put(a, 4, uint64(v)) }

func (w *spcWorld) copyDw(dst, src, n uint32) {
	for i := uint32(0); i < n; i++ {
		w.put32(dst+4*i, w.u32(src+4*i))
	}
}

// List layout {vt, count, cap, data}.

// grow is 0x4addf0(list, n): a bigger data block when n exceeds the capacity.
func (w *spcWorld) grow(l, n uint32) {
	if int32(n) <= int32(w.u32(l+8)) {
		return
	}
	d, old := w.alloc(4*n), w.u32(l+0xc)
	for i := uint32(0); int32(i) < int32(w.u32(l+4)); i++ {
		w.put32(d+4*i, w.u32(old+4*i))
	}
	w.put32(l+0xc, d)
	w.put32(l+8, n)
}

// push1 is an append site that runs at most twice on an instance list freshly
// made with capacity 5: its 0x4addf0 / inline grow path is reached only after
// the 5-entry allocation failed (notes/re/cov-exempt.d/4fb4c0.tsv).
func (w *spcWorld) push1(l, e uint32) {
	if w.u32(l+4)+1 > w.u32(l+8) {
		spcPanic("single append grows a fresh 5-entry list (allocation failure only)")
	}
	w.push(l, e)
}

// visual1 is visual at a push1 site.
func (w *spcWorld) visual1(inst, e uint32) {
	if e != 0 {
		w.put8(e+0x1e6, 0)
		w.push1(inst+0x100, e)
	}
}

func (w *spcWorld) push(l, e uint32) {
	n := w.u32(l + 4)
	w.grow(l, n+1)
	w.put32(w.u32(l+0xc)+4*n, e)
	w.put32(l+4, n+1)
}

// assign copies list src into list dst (count reset, grow, copy).
func (w *spcWorld) assign(dst, src uint32) {
	w.put32(dst+4, 0)
	n := w.u32(src + 4)
	w.grow(dst, n)
	for i := uint32(0); int32(i) < int32(n); i++ {
		w.put32(w.u32(dst+0xc)+4*i, w.u32(w.u32(src+0xc)+4*i))
	}
	w.put32(dst+4, n)
}

// newList is 0x489bb0 / 0x501f80 / 0x501e50 (vt, 5-entry block).
func (w *spcWorld) newList(l, n, vt uint32) {
	w.put32(l, vt)
	w.put32(l+0xc, w.alloc(n))
	w.put32(l+4, 0)
	w.put32(l+8, 5)
}

// visual appends a 0x4ad* visual object to the inst+0x100 list (byte +0x1e6 = 0).
func (w *spcWorld) visual(inst, e uint32) {
	if e == 0 {
		return
	}
	w.put8(e+0x1e6, 0)
	w.push(inst+0x100, e)
}

func spcPct(v, x uint32) uint32 { return v + v*x/100 } // 0x517f90

// aca00 is 0x4aca00.
func (w *spcWorld) aca00(spell uint32) bool {
	i := spell - 0x30
	return i <= 0x2d && w.u8(0x4aca2c+i) == 0
}

// aca60 is 0x4aca60: whether a failed roll may backfire.
func (w *spcWorld) aca60(spell uint32) bool {
	cls := w.u32(w.spellRecord(spell) + 0x137)
	if cls > 10 {
		return false
	}
	switch w.u8(0x4acad8 + cls) {
	case 0:
		s := spell - 3
		return s <= 0x47 && w.u8(0x4acaec+s) == 0
	case 1:
		return spell != 0x4d && spell != 0x76 && spell != 0x83
	case 2:
		return false
	case 3:
		return spell == 0x27
	}
	spcPanic("0x4aca60 table byte outside its jump table")
	return false
}

// power is 0x4ff790(v, spell, level).
func (w *spcWorld) power(v, spell, level uint32) uint32 {
	rec := w.spellRecord(spell)
	p := int32(v>>1) + int32(level) + (int32(w.u32(rec+0x49))/2+int32(w.u32(rec+0x56)))/2
	if w.spellType(spell, false) == 7 {
		p -= 3
	}
	return uint32(max(p, 0))
}

// skills is 0x4ffbd0(c, mask, flag): the primary skill plus the masked others.
func (w *spcWorld) skills(c uint32, mask byte, flag bool) uint32 {
	s := w.u32(c + 0x69)
	if s == 0xffffffff {
		spcPanic("character without primary skill (0x4ffbf6 asserts)")
	}
	v := int32(-1)
	if t := w.u32(0x616310 + 4*s); t != 0xffffff01 {
		v = int32(w.u32(c+0x8d+4*s) + t)
	}
	if v <= 0 && !flag {
		return uint32(v)
	}
	for i := uint32(0); i < 15; i++ {
		if w.u32(c+0x8d+4*i) == 0 || i == s || w.u8(0x61634c+i)&mask == 0 {
			continue
		}
		t := w.u32(0x616310 + 4*i)
		if t == 0xffffff01 {
			continue
		}
		if x := int32(w.u32(c+0x8d+4*i) + t); x > 0 {
			v += x
		}
	}
	return uint32(v)
}

// visualOf is 0x4e5950(id): the monster's visual object or 0.
func (w *spcWorld) visualOf(id uint32) uint32 {
	if id == 0xffffffff {
		return 0
	}
	h, ok := w.monsterHandle(id)
	if !ok {
		return 0
	}
	return w.u32(w.monsterRecord(h) + 0xc)
}

// notice is 0x590950(idx, ...): the message line for party member idx.
func (w *spcWorld) notice(idx uint32) {
	w.stub(0x58aad0, 8, 0x64bf5c, w.charBase(idx)+5, 0)
	w.stub(0x58b410, uint32(w.u8(w.u32(0x685178)+idx*0x106+0xf1)), 0, 0, 0xffffffff)
}

func (w *spcWorld) monPos(m, dst uint32, lift bool) {
	b := w.u32(m+0xc) + 0x18
	w.copyDw(dst, b+0x100, 3)
	if lift {
		w.putF(dst+4, w.f32(b+0x104)+w.f32(b+0x178))
	}
}

// reflect is 0x4fea50(spell, src, tgt): a backfired spell turns on its caster.
func (w *spcWorld) reflect(spell, src, tgt uint32) {
	if t := w.u32(src); t < 1 || t > 3 {
		spcPanic("source type outside 1..3 (0x4fea50 asserts)")
	}
	if t := w.u32(tgt); t < 1 || t > 9 {
		spcPanic("target type outside 1..9 (0x4fea50 asserts)")
	}
	if w.u8(src+0x1c) != 0 {
		spcPanic("source already reflected (0x4fea50 asserts)")
	}
	var m uint32
	if w.isMon(src) {
		m = w.findMonster(w.u32(src + 8))
	}
	// 0x4fea50 switches on class-1 through a 10-entry table.
	switch spell, t := spell, w.spellType(spell, false); t {
	case 1, 4:
		w.stub(0x4fe740, src, tgt)
	case 3:
		if spell != 3 && spell != 0x29 {
			w.stub(0x4fe740, src, tgt)
		}
	case 2, 7, 10:
	case 5, 6:
		if t == 5 {
			a, b := w.local(12), w.local(12)
			switch {
			case w.isChar(src):
				w.copyDw(a, w.u32(0x65a0f8)+0x8c, 3)
			case w.isMon(src):
				if w.stub(0x4c78e0, a) == 0 {
					w.stub(0x4c72a0, a)
				}
			default:
				w.copyDw(a, src+0xc, 3)
			}
			w.copyDw(b, tgt+0x10, 3)
			w.stub(0x434f20, a, b, 1, 0xfffffffd, 0xfffffffd, 1, 0)
			w.copyDw(tgt+0x10, b, 3)
		}
		old := w.local(12)
		w.copyDw(old, src+0xc, 3)
		w.copyDw(src+0xc, tgt+0x10, 3)
		switch {
		case w.isChar(src):
			if t == 5 {
				w.copyDw(tgt+0x10, w.u32(0x65a0f8)+0x8c, 3)
			} else {
				w.copyDw(tgt+0x10, w.u32(0x659c0c)+0x100, 3)
			}
		case w.isMon(src):
			w.monPos(m, tgt+0x10, t == 5)
		default:
			w.copyDw(tgt+0x10, old, 3)
		}
		w.put32(src, 3)
	default:
		spcPanic(fmt.Sprintf("spell class %d outside 0x4fea50's table (assert)", t))
	}
}

// engage is 0x4ecc80(src, tgt): combat targeting side effects.
func (w *spcWorld) engage(src, tgt uint32) {
	p := w.u32(0x6850e5)
	if p == 2 || w.stub(0x536190, tgt)&0xff == 0 {
		return
	}
	sel := w.u32(0x68518d)
	if p == 0 && !(w.isChar(src) && w.u32(src+4) == sel || w.u32(tgt) == 1 && w.u32(tgt+4) == sel) {
		return
	}
	switch w.u32(tgt) {
	case 3:
		if w.u32(tgt+8) == 0xffffffff {
			spcPanic("monster target without id (0x4ecc80 asserts)")
		}
		w.stub(0x48f650, w.findMonster(w.u32(tgt+8)))
	case 4:
		if w.u32(tgt+0xc) == 0xffffffff {
			spcPanic("group target without id (0x4ecc80 asserts)")
		}
		g := w.group(w.u32(tgt + 0xc))
		w.stub(0x48f650, w.findMonster(w.u32(g+0x9f)))
	case 6:
		w.stub(0x48f800, 0, 0, 0)
	}
}

// release is 0x4e6020(m, mode).
func (w *spcWorld) release(m, mode uint32) {
	if (mode == 0 || mode == 2) && w.u32(m+0x2fd) == 1 && w.u32(w.u32(m+0xc)+0x74) == 0 {
		w.stub(0x4537e0)
		w.put8(m+0x255, 0)
	}
	w.put32(m+0x2fd, mode)
	w.groupCount(w.group(w.u32(m + 4)))
}

func (w *spcWorld) arg(n uint32) uint32 { return w.u32(mstStackBase + 4 + 4*n) }

// cast is 0x4fb4c0.
func (w *spcWorld) cast(spell, src, tgt, level, bonus, fail, keep, out, mode, ext2, ext1 uint32) uint32 {
	l1, l2 := w.local(16), w.local(16)
	w.newList(l1, 0x14, 0x5ebfe0)
	w.newList(l2, 0x14, 0x5ebfe0)
	if out != 0 {
		w.put32(out, 0)
	}
	inst := w.alloc(0x1c8)
	w.newList(inst+0xe0, 0x14, 0x5ebfe0)
	w.newList(inst+0xf0, 0x14, 0x5ebfe0)
	w.newList(inst+0x100, 20, 0x5ec280)
	w.newList(inst+0x110, 20, 0x5ec27c)
	w.alloc(0x14) // 0x501fd0 at +0x124; its fields are wiped right after
	w.copyDw(inst+8, src, 13)
	w.copyDw(inst+0x3c, tgt, 8)
	caster := uint32(0xffffffff)
	if w.isChar(src) {
		caster = w.u32(src + 4)
	}
	w.put8(src+0x1c, 0)

	rec := w.spellRecord(spell)
	r133 := w.u32(rec + 0x133)
	cheat := w.u8(0x689b68) != 0 && spell != 0x76
	f := int32(fail)
	if cheat {
		f = 100
	}
	noMana := r133 == 0 && w.u8(0x652da4) != 0
	if noMana {
		f = 100
	}
	if mode == 4 && w.u8(0x689b68) == 0 { // 0x4fb718 tests the raw byte: spell 0x76 is halved only without it
		f >>= 1
	}
	if w.u8(0x68d810) != 0 {
		spcPanic("debug log flag 0x68d810 set (fixture keeps it 0)")
	}
	fizzle := false
	if f != 0 {
		if roll := int32(w.r.R(100)); roll < f {
			thr := f
			switch {
			case noMana:
				thr = 0
			case mode != 4 && !cheat:
				thr = 0
				if f > 5 {
					thr = f / 3
				}
			}
			if !w.aca60(spell) {
				thr = 0
			}
			if thr <= roll {
				fizzle = true
			} else {
				w.reflect(spell, src, tgt)
				w.put8(src+0x1c, 1)
				keep = 0
				w.stub(0x408860, 0x6193d4, 0)
			}
		}
	}
	if fizzle {
		w.stub(0x408860, 0x6193b0, 0)
		if caster != 0xffffffff && w.r.R(100) < 0x46 {
			w.stub(0x52e690, w.charBase(caster), w.u32(0x68c558), 0, w.u32(0x5ed8c8), w.u32(0x5ed914))
		}
		switch {
		case mode == 2 || mode == 3:
			if w.u32(src) != 1 {
				spcPanic("fizzle message for a non-character source (0x4fcd8b asserts)")
			}
			if w.u8(0x68510c) != 0 {
				w.notice(w.u32(src + 4))
			} else {
				w.stub(0x5905f0)
			}
		case w.u8(0x68510c) != 0:
			w.stub(0x58ac00)
		default:
			w.stub(0x5905f0)
		}
		return w.tail(inst, src, level, out, true)
	}

	if w.u8(src+0x1c) == 0 && w.u8(src+0x18) == 0 && w.u8(src+0x1b) == 0 && r133 != 4 && spell != 0x83 {
		w.stub(0x4ff220, spell, src, tgt)
	}
	if ext2 == 0 && ext1 == 0 {
		w.stub(0x4fd030, spell, level, src, tgt, l1, l2, 0)
		if spell == 0x3c {
			w.putF(tgt+0x14, w.f32(tgt+0x14)-w.f32(0x5ebc64))
			e := uint32(1)
			if w.isChar(src) != (w.u8(src+0x1c) != 0) {
				e = 2
			}
			w.stub(0x54ff20, w.u32(tgt+0x10), w.u32(tgt+0x14), w.u32(tgt+0x18), e, 0)
			st0 := math.Float64frombits(uint64(w.u32(spcST0)) | uint64(w.u32(spcST0+4))<<32)
			pos, o := w.local(12), w.local(12)
			w.copyDw(pos, tgt+0x10, 3)
			d := 0x616ec8 + 0x30*uint32(int32(int8(w.u8(0x616f40+level))))
			rad := float32(math.Float64frombits(uint64(w.u32(d))|uint64(w.u32(d+4))<<32) + float64(w.f32(0x5ebc40)))
			if w.stub(0x437f30, pos, math.Float32bits(float32(st0)), math.Float32bits(rad), 1, o, 1, 0, 0, 5, 1) != 0 {
				w.copyDw(tgt+0x10, o, 3)
			}
		}
	} else {
		if ext2 != 0 {
			w.assign(l2, ext2)
		}
		if ext1 != 0 {
			w.assign(l1, ext1)
		}
	}

	blk := w.local(0x30)
	src1c := w.u8(src+0x1c) != 0
	var v uint32
	switch {
	case sdmSource(w.mcaWorld, src, true):
		if w.u8(src+0x19) != 0 {
			v = uint32(w.u8(src + 0x1f))
		} else {
			var mask byte
			if w.u8(rec+0x120) != 0 {
				mask |= 8
			}
			if w.u8(rec+0x11f) != 0 {
				mask |= 2
			}
			if w.u8(rec+0x5a) != 0 {
				mask |= 1
			}
			if w.u8(rec+0x48) != 0 {
				mask |= 4
			}
			v = w.power(w.skills(w.charBase(w.u32(src+4)), mask, true), spell, level)
		}
	case w.isMon(src):
		v = w.power(uint32(w.u8(w.template(w.findMonster(w.u32(src+8)))+0x24f)), spell, level)
	default:
		if w.u32(src) != 3 {
			spcPanic("power source of unknown type (0x4fb4c0 asserts)")
		}
		p := (int32(w.u32(rec+0x49))/2+int32(w.u32(rec+0x56)))/2 + int32(level)
		if w.spellType(spell, false) == 7 {
			p -= 3
		}
		v = uint32(max(p, 0))
	}
	var sub uint32
	switch spell {
	case 0x46:
		sub = 2
	case 0x57:
		sub = 4
	case 0x5a, 0x5d, 0x5e:
		sub = 6
	}
	pw := uint32(0)
	if int32(v) >= int32(sub) {
		pw = v - sub
	}
	w.put32(blk+0x18, spcPct(pw, bonus>>1))
	if !w.aca00(spell) {
		d := w.u32(rec + 0x51)
		d = d&^0xff0000 | uint32(byte(byte(d>>16)*byte(level)))<<16
		w.put32(blk+4, d)
	}
	w.put32(blk+0x20, level)
	w.put32(blk+0x24, bonus)
	w.put32(blk+0x28, w.u32(rec+0x4d))
	w.put32(blk+0x2c, w.u32(rec+0x44))

	if w.u8(rec+0x13f) != 0 {
		r140 := w.u32(rec + 0x140)
		q := w.local(0x20)
		if w.spellType(spell, false) == 6 {
			if e := w.stub(0x544630, r140, src, q, blk, 1, 0xffffffff, 0x270f, q); e != 0 {
				w.push1(inst+0x110, e)
			}
			w.put8(inst+0x122, 1)
		} else {
			t := w.u32(0x65bde0) + r140*0x1e5
			w.copyDw(blk+8, t+0x155, 4)
			w.put32(blk+0x1c, w.u32(t+0x150))
			for i := uint32(0); int32(i) < int32(w.u32(l1+4)); i++ {
				if !src1c && w.u8(src+0x1b) == 0 {
					w.stub(0x5471d0, src, q)
				}
				if e := w.stub(0x544630, r140, src, q, blk, 1, w.u32(rec+0x12f), 0x270f); e != 0 {
					w.push(inst+0x110, e)
				}
			}
			for i := uint32(0); int32(i) < int32(w.u32(l2+4)); i++ {
				if e := w.stub(0x544630, r140, src, q, blk, 1, w.u32(rec+0x12f), 0x270f); e != 0 {
					w.push(inst+0x110, e)
				}
			}
		}
	} else {
		w.visuals(spell, rec, inst, src, tgt, level, l1, l2, src1c)
	}

	// store
	w.put32(inst, spell)
	w.copyDw(inst+0x5c, src, 13)
	w.copyDw(inst+0x90, tgt, 8)
	w.copyDw(inst+0xb0, blk, 12)
	w.assign(inst+0xe0, l1)
	w.assign(inst+0xf0, l2)
	w.put8(inst+0x120, byte(keep))
	if spell == 0x26 {
		w.put8(inst+0x121, 1)
		w.put32(inst+4, w.stub(0x5519c0, inst+0xb0))
		for i := uint32(0); int32(i) < int32(w.u32(0x689b5c)); i++ {
			q := w.u32(w.u32(0x689b64) + 4*i)
			if w.u32(q) != 0x26 {
				continue
			}
			w.put32(q+4, 0)
			for u := uint32(0); u < w.listCount(w.u32(0x683fad)); u++ {
				if m := w.monsterRecord(u); !w.act15(w.u32(m + 0xc)) {
					w.release(m, 0)
				}
			}
			break
		}
	}
	f97, f9b := w.u8(0x683f97) != 0, w.u8(0x683f9b) != 0
	if w.u32(0x68ec78) == 7 && !f97 && !f9b {
		c := w.u32(0x689b5c)
		if int32(c+1) > int32(w.u32(0x689b60)) {
			d, old := w.alloc(4*(c+1)), w.u32(0x689b64)
			for i := uint32(0); i < c; i++ {
				w.put32(d+4*i, w.u32(old+4*i))
			}
			w.put32(0x689b64, d)
			w.put32(0x689b60, c+1)
		}
		w.put32(w.u32(0x689b64)+4*c, inst)
		w.put32(0x689b5c, c+1)
	} else {
		w.dispatch(inst)
		if f97 || f9b {
			for i := uint32(0); int32(i) < int32(w.u32(inst+0x104)); i++ {
				w.put8(w.u32(w.u32(inst+0x10c)+4*i)+0x1e6, 1)
			}
		}
	}
	w.engage(src, tgt)
	if w.u8(src+0x1c) != 0 {
		switch {
		case mode == 4:
			w.put8(inst+0x124, 1)
		case w.u8(0x68510c) != 0:
			w.stub(0x58ac00)
		default:
			w.stub(0x5905f0)
			w.put8(inst+0x124, 1)
		}
		if caster != 0xffffffff {
			if w.r.R(2) == 0 {
				w.stub(0x52e690, w.charBase(caster), w.u32(0x5ee5c8), 0, w.u32(0x5ed8c8), w.u32(0x5ed914))
			} else {
				w.stub(0x52e5c0, w.u32(0x5ee5cc), caster, 0, w.u32(0x5ed8c8))
			}
		}
	}
	return w.tail(inst, src, level, out, false)
}

func (w *spcWorld) tail(inst, src, level, out uint32, fizzle bool) uint32 {
	if out != 0 {
		w.put32(out, level)
	}
	if !fizzle {
		if w.u8(src+0x1c) != 0 {
			return 3
		}
		return 1
	}
	if w.isMon(inst + 8) {
		m := w.findMonster(w.u32(inst + 0x10))
		if g := w.u32(0x6836a8); w.u8(0x683f94) != 0 && w.u32(g+0x7b0) != 0 && w.u32(g+0x7b8) != 0 && w.u32(w.u32(g+0x7b8)) == w.u32(m) {
			w.put32(g+0x7b0, 3)
		}
	}
	w.put32(inst+0x17e, 0x5ebfec)
	w.put32(inst+0x110, 0x5ebfe8)
	w.put32(inst+0x100, 0x5ebfe4)
	w.put32(inst+0xf0, 0x5ebfe0)
	w.put32(inst+0xe0, 0x5ebfe0)
	return 2
}

// visuals is 0x4fb4c0's non-missile branch.
func (w *spcWorld) visuals(spell, rec, inst, src, tgt, level, l1, l2 uint32, src1c bool) {
	cls := w.spellType(spell, false)
	if spell == 0x31 {
		cls = 3
	}
	drop := func() { w.putF(tgt+0x14, w.f32(tgt+0x14)-w.f32(0x5ebc64)) }
	at := func() uint32 { p := w.local(12); w.copyDw(p, tgt+0x10, 3); return p }
	switch cls {
	case 0, 1, 3:
		if spell == 0x4b || spell == 0x49 {
			w.visual1(inst, w.stub(0x4ad080, rec+0x5b, level, 0, 0))
			return
		}
		for i := uint32(0); int32(i) < int32(w.u32(l1+4)); i++ {
			w.visual(inst, w.stub(0x4ad630, rec+0x5b, level, w.visualOf(w.u32(w.u32(l1+0xc)+4*i)), 0, 0))
		}
		for i := uint32(0); int32(i) < int32(w.u32(l2+4)); i++ {
			flag := !src1c
			if w.mstSpellFits(spell) {
				flag = src1c
			}
			b := uint32(0)
			if flag {
				b = 1
			}
			w.stub(0x59af40, w.u32(w.u32(l2+0xc)+4*i), w.u32(rec+0x133), b, spell)
		}
	case 2, 4, 7:
		switch spell {
		case 0x5f:
		case 0x62:
			drop()
			w.visual1(inst, w.stub(0x4ad430, at(), w.u32(0x65be1c)+0xab79, level, 0, 0))
		default:
			for i := uint32(0); int32(i) < int32(w.u32(l1+4)); i++ {
				w.visual(inst, w.stub(0x4ad630, rec+0x5b, level, w.visualOf(w.u32(w.u32(l1+0xc)+4*i)), 0, 0))
			}
			if w.u32(l2+4) != 0 {
				w.visual(inst, w.stub(0x4ad080, rec+0x5b, level, 0, 0))
			}
		}
	case 5:
		switch {
		case w.isChar(src):
			if e := w.stub(0x4ad8a0, rec+0x5b, level, 0, 0, 0); e != 0 {
				w.put8(e+0x1e6, 0)
				w.put8(e+0x1e7, 1)
				w.push1(inst+0x100, e)
			}
		case w.isMon(src):
			w.visual1(inst, w.stub(0x4ad8a0, rec+0x5b, level, w.visualOf(w.u32(src+8)), 0, 0))
		default:
			w.visual1(inst, w.stub(0x4adb20, rec+0x5b, level, 0, 0, 0, 0))
		}
	case 6:
		switch {
		case spell == 0x76 && w.u32(l2+4) != 0:
			w.visual1(inst, w.stub(0x4ad430, w.local(12), w.u32(0x65be1c)+0xce65, 2, 0, 0))
		case spell == 0x76:
			drop()
			w.visual1(inst, w.stub(0x4ad430, at(), w.u32(0x65be1c)+0xce65, 1, 0, 0))
		default:
			drop()
			w.visual1(inst, w.stub(0x4ad430, at(), rec+0x5b, level, 0, 0))
		}
	case 8:
		if spell == 0x26 {
			drop()
			w.visual1(inst, w.stub(0x4ad430, at(), w.u32(0x65be1c)+0x42b5, level, 0, 0))
			if e := w.stub(0x4ad430, at(), 0x6192fc, level, 0, 0); e != 0 {
				w.put8(e+0x1e6, 0)
				w.put8(w.u32(e+0x1e0)+0x71, 3)
				w.push1(inst+0x100, e)
			}
			return
		}
		if spell != 0x3c {
			drop()
		}
		w.visual1(inst, w.stub(0x4ad430, at(), rec+0x5b, level, 0, 0))
	case 9:
	case 10:
		w.visual1(inst, w.stub(0x4ad080, rec+0x5b, level, 0, 0))
	default:
		w.stub(0x4ad080, 0x619380, 0, 0, 0)
		w.stub(0x408860, 0x61935c, 0)
	}
}

// dispatch is 0x54ba00(inst): the per-spell effect handler.
func (w *spcWorld) dispatch(inst uint32) {
	spell := w.u32(inst)
	rec := w.spellRecord(spell)
	if w.u8(rec+0x13f) != 0 && !w.aca00(spell) {
		if t := w.spellType(spell, false); t != 6 && t != 2 {
			return
		}
	}
	if w.u8(inst+0x74) != 0 && spell != 9 {
		w.put8(inst+0x124, 1)
	}
	d0, d4 := w.u32(inst+0xd0), w.u32(inst+0xd4)
	back := w.u8(inst+0x78) != 0
	res := byte(1)
	h := func(a uint32, args ...uint32) byte { return byte(w.stub(a, append([]uint32{inst}, args...)...)) }
	eff := func(k, pct uint32) { h(0x54d5c0, k, pct, 0) }
	all := func(flag uint32, ks ...uint32) byte {
		b := byte(1)
		for _, k := range ks {
			b &= h(0x54df00, k, flag)
		}
		return b
	}
	set := func(off uint32) { w.put8(inst+off, 1) }
	clamp7 := func() uint32 {
		v := spcPct(d0, d4)
		if v > 6 {
			v = 7
		}
		return v
	}
	switch spell {
	case 1, 5, 10, 0xb, 0x19, 0x4f:
		return
	case 2, 0x35, 0x3b, 0x3e:
		h(0x54d380)
	case 3:
		h(0x550a00)
	case 6, 0x44:
		if !back {
			res = h(0x54f190)
		} else {
			h(0x54e950)
		}
	case 7:
		eff(3, 100)
	case 8, 0x11, 0x14, 0x1a, 0x20, 0x21, 0x28, 0x2d, 0x40:
		h(0x54cbf0)
	case 0xc:
		eff(0xf, 100)
	case 0xd, 0x2c:
		if !back {
			res = h(0x54f520)
		} else {
			h(0x54f8c0)
		}
	case 0xe, 0x75:
		eff(6, 100)
	case 0xf:
		eff(0xc, 100)
	case 0x10:
		if !back {
			res = all(0, 3, 4, 6, 0xf, 0xc)
		} else {
			eff([5]uint32{3, 4, 6, 0xf, 0xc}[min(w.r.R(5), 4)], 100)
		}
	case 0x12: // 0x58a9c0(level, +0x75, +0x78): trap level into the current trap object
		v := clamp7()
		if w.u8(0x683f99) == 0 {
			w.stub(0x58ac00)
		} else {
			t := w.u32(0x68f2d4)
			w.put32(t+0x14c, v)
			w.put32(w.u32(t+0x10)+0x68, v)
			w.put8(w.u32(t+0xc)+0x140, 1)
		}
		set(0x124)
	case 0x13, 0x15, 0x1b, 0x36, 0x38, 0x3d, 0x41:
		if !back {
			h(0x54e3f0, map[uint32]uint32{0x13: 1, 0x15: 2, 0x1b: 3, 0x36: 4, 0x38: 5, 0x3d: 6, 0x41: 7}[spell])
			set(0x125)
		} else {
			switch spell {
			case 0x13:
				eff(4, 100)
			case 0x1b:
				h(0x54e950)
			case 0x38:
				eff(5, 100)
			case 0x15, 0x36, 0x3d, 0x41:
			default:
				spcPanic("back arm index outside the table (0x54bb41 asserts)")
			}
		}
	case 0x17:
		if !sdmSource(w.mcaWorld, inst+0x5c, false) {
			spcPanic("spell 0x17 from a non-character (0x54c057 asserts)")
		}
		it := w.u32(inst + 0xac)
		w.stub(0x520b40, it, d0, d4)
		if w.u8(it+6) != 0 && w.u8(it+0xb) != 0 {
			set(0x125)
		}
	case 0x18:
		eff(0xb, 100)
	case 0x1d:
		eff(5, 100)
	case 0x1e, 0x7b:
		eff(6, 100)
		w.stub(0x4f0e80, inst+0xa0, d0*15000+25000, 0)
		if w.u8(0x683f94) == 0 {
			set(0x125)
		}
	case 0x1f:
		eff(0xe, 100)
	case 0x22:
		if !back {
			res = all(0, 0x10, 0xe)
		} else {
			eff(0x10, 100)
		}
	case 0x23:
		if !back {
			res = all(0, 7)
		} else {
			loc := w.local(4)
			t := w.strength(inst, 7, loc)
			w.put32(inst+0xd8, uint32(w.r.R(int(d0)))+1+t)
			x := uint32(w.r.R(int(d0/3))) + 1 + w.u32(loc)
			h(0x54d5c0, 7, 100, x)
		}
	case 0x25, 0x43:
		eff(0x10, 100)
	case 0x26:
		w.sweep(inst)
	case 0x27:
		// 0x587c80(level, +0x75, +0x78): trap disarm (D4 0x58a930) or lock pin (D4 0x5871a0,
		// this = [0x68f2c0]); their eax is ignored, the trap / lock objects are not read here
		v, b75, b78 := clamp7(), uint32(w.u8(inst+0x75)), uint32(w.u8(inst+0x78))
		switch {
		case w.u8(0x683f99) != 0:
			w.stub(0x58a930, v, b75, b78)
		case w.u8(0x683f98) == 0:
			w.stub(0x58ac00)
		default:
			w.stub(0x5871a0, v, b75, b78)
		}
		set(0x124)
	case 0x29:
		h(0x5508e0)
		set(0x124)
	case 0x2a:
		h(0x54e950)
		eff(4, 0x5a)
		eff(0x11, 0x19)
	case 0x2e:
		eff(8, 100)
	case 0x30, 0x31, 0x4c, 0x50, 0x51, 0x5d:
		h(0x54cdd0)
	case 0x33:
		res = all(0, 2)
	case 0x3a:
		if back {
			eff(9, 100)
		} else {
			h(0x5517c0)
		}
	case 0x3c:
		h(0x5500c0)
	case 0x45:
		eff(9, 100)
	case 0x46, 0x57, 0x5a, 0x5e:
		eff(0x12, 100)
	case 0x47:
		h(0x54e950)
		eff(0xb, 0x19)
	case 0x48:
		h(0x54d100)
		set(0x125)
	case 0x49:
		h(0x5507d0)
		set(0x125)
	case 0x4a:
		if !back {
			res = all(0, 0xb, 0xd)
		} else {
			eff(0xb, 100)
		}
	case 0x4b:
		if !sdmSource(w.mcaWorld, inst+0x5c, false) {
			spcPanic("spell 0x4b from a non-character (0x54c1cb asserts)")
		}
		c := w.charBase(w.u32(inst + 0x60))
		w.stub(0x4506c0, w.u32(0x659ab4))
		w.put32(c+0x1813, w.u32(0x686a70))
		w.put8(c+0x1861, 1)
		set(0x125)
	case 0x4e:
		h(0x54e950)
		eff(0xc, 0x19)
	case 0x52, 0x54:
		h(0x54ec80)
	case 0x55:
		h(0x54dbe0, 0xb, 6, 100, 0, 0)
	case 0x56, 99:
		h(0x54fa30)
		set(0x124)
	case 0x58:
		res = all(0, 0x12)
	case 0x59:
		eff(0xd, 100)
	case 0x5b:
		h(0x54e950)
		eff(0xb, 0x4b)
	case 0x5c:
		h(0x54e950)
		eff(0x11, 0x32)
	case 0x5f:
		a := float32(float64(d0)*float64(w.f32(0x5ebcc8)) + float64(w.f32(0x5ebc7c)))
		o := w.stub(0x4ae080, math.Float32bits(a))
		w.put32(o, w.u32(o)&^0x18)
		if w.u8(rec+0x14b) != 0 { // 0x517a70 (排除 message format) -> 0x408860 (排除 log)
			w.stub(0x408860, w.stub(0x517a70, 0x61aa9c, rec+0x14b), 0)
		}
		h(0x54e950)
	case 4, 9, 0x16, 0x1c, 0x24, 0x2b, 0x2f, 0x32, 0x34, 0x37, 0x39, 0x3f, 0x42, 0x4d, 0x53, 0x60, 0x61, 0x62, 0x65, 0x76:
		h(0x54e950)
	case 100:
		b := h(0x54f190)
		b &= h(0x54f520)
		for k := uint32(2); k < 0x12; k++ {
			if k != 10 {
				b &= h(0x54df00, k, 1)
			}
		}
		res = b
	case 0x72:
		b := h(0x54f190)
		w.put8(inst+0xb6, w.u8(inst+0xb6)<<1)
		res = b & h(0x54f520)
		set(0x124)
	case 0x73:
		for i := uint32(0); int32(i) < int32(w.u32(inst+0xf4)); i++ {
			if int32(i) >= int32(w.u32(inst+0xf4)) {
				spcPanic("0x54c0fe: list index past its count")
			}
			id := w.u32(w.u32(inst+0xfc) + 4*i)
			if id == 0xffffffff {
				spcPanic("party target -1 (0x54c10b asserts)")
			}
			v := w.stub(0x517970, inst+0xb4)
			if v != 9999 {
				v = spcPct(v, d4)
			}
			w.stub(0x52b910, id, v)
		}
		set(0x125)
	case 0x74:
		res = all(0, 0x11, 0xf)
	case 0x78:
		h(0x54df00, 1, 1)
	case 0x7c:
		if int32(w.u32(inst+0xf4)) > 0 {
			p := w.stub(0x517970, inst+0xb4)
			if p < 100 {
				p = w.stub(0x517970, inst+0xb4)
			} else {
				p = 100
			}
			g := w.u32(0x685189)
			w.put32(0x685189, g-p*g/100)
			if w.u8(0x68510c) == 0 { // 0x54c3ce
				w.status()
			}
			w.stub(0x5905f0)
			set(0x124)
		}
	case 0x7d:
		h(0x550c10)
	case 0x7e:
		h(0x5510b0)
	case 0x7f:
		v := spcPct(d0*0x32, d4)
		if int32(w.u32(inst+0xf4)) > 0 {
			w.stub(0x52b550, v, 0)
			for e := uint32(0x686924); e < 0x6869f0; e += 0x11 {
				if w.u8(e-5) != 0 { // clear the light slot, rebuild party effects, refresh the view
					w.put8(e-5, 0)
					w.put32(e-4, 0)
					w.put32(e, 0)
					w.put32(e+8, 0)
					w.stub(0x50e700)
					if w.u32(0x68ec78) == 7 { // 0x5af2d0: screen rect clear + dirty mark (排除)
						w.stub(0x4263f0, 0x7f, 0x14, 0x201, 0x28)
						w.stub(0x422d50, 0x7f, 0x14, 0x201, 0x28, 0)
					}
					w.stub(0x562a50, 0x800100)
				}
			}
		}
		set(0x124)
	case 0x81:
		h(0x54e950)
		eff(0x10, 0x32)
	case 0x82:
		h(0x54e610)
	case 0x83:
		w.stub(0x506280, 0x83)
		h(0x54e950)
	default:
		w.stub(0x58aad0, 7, 0x61e258, rec+0x9b)
	}
	if w.u8(0x68510c) == 0 && w.u8(inst+0x124) == 0 && !back {
		w.status()
		w.stub(0x5905f0)
		set(0x124)
	}
	if w.u8(inst+0x120) != 0 && res == 0 {
		if w.u8(inst+0x74) == 0 {
			if sdmSource(w.mcaWorld, inst+0x5c, false) {
				idx := w.u32(inst + 0x60)
				c := w.charBase(idx)
				w.stub(0x52af50, idx, w.spLevel(spell, d0), 1, 0)
				// 0x54c63b: recast at PL 8 while the member still has the SP
				// and 0x4fa4d0 returns 2; rec/SP are re-read every pass.
				out := w.local(4) // 0x54ba00's esp+0x2c, reused every pass
				for int32(w.spLevel(spell, 1)) <= int32(w.u32(c+0xb1d)) &&
					int32(w.u32(c+0xb45+4*w.u32(w.spellRecord(spell)+0x133))) >= int32(w.u32(w.spellRecord(spell)+0x49)) {
					if w.charCast(w.u32(inst+0x60), spell, 8, out, 1) != 2 {
						break
					}
					w.stub(0x52af50, w.u32(inst+0x60), w.u32(out), 1, 0)
				}
			}
		} else {
			w.cast(spell, inst+0x5c, inst+0x90, d0, 0, 0, 1, w.local(4), 0, 0, 0)
		}
	}
	w.reflectBest(inst)
	if spell != 0x17 && w.u32(0x68ec78) == 6 {
		w.stub(0x590bd0, 0xffffffff)
	}
}

// status is 0x5905e0 then 0x5905f0 / 0x5905c0(1, -1).
func (w *spcWorld) status() {
	if w.u8(0x69b7b8) != 0 {
		w.stub(0x5905f0)
		w.put8(0x69b7b8, 1)
	}
}

func (w *spcWorld) spLevel(spell, level uint32) uint32 { // 0x52c320
	if level == 8 {
		return 0
	}
	return w.u32(w.spellRecord(spell)+0x56) + level
}

// strength is 0x553910(inst, k, out).
func (w *spcWorld) strength(inst, k, out uint32) uint32 {
	switch w.u32(inst + 0x90) {
	case 1:
		c := w.charBase(w.u32(inst + 0x94))
		if k == 7 && out != 0 {
			w.put32(out, w.u32(c+0xb09))
		}
		return w.u32(c + 0xa01 + 4*k)
	case 3:
		m := w.findMonster(w.u32(inst + 0x98))
		if k == 7 && out != 0 {
			w.put32(out, w.u32(m+0x10b))
		}
		return w.u32(m + 0x57 + 4*k)
	}
	spcPanic("0x553910 target type outside 1/3 (assert)")
	return 0
}

// sweep is 0x551500(inst): the area query (0x42ef00, geometry, case input)
// returns hit ids; each awake, visible monster with sweep state 0/1 rolls its
// mental resistance (0x552410) and is released (0x4e6020), alone or by group
// (0x5117d0).
func (w *spcWorld) sweep(inst uint32) {
	w.stub(0x46e440, w.u32(0x659ab4)) // 0x451280; ST0 only sizes the query box
	buf := w.local(4)
	w.put32(buf, w.alloc(0x400))
	n := w.stub(0x42ef00, buf, 0, 0, 0)
	if n > 6 {
		spcPanic("0x42ef00 hit count past the fixture's 6 ids")
	}
	for i := uint32(0); i < n; i++ {
		m := w.findMonster(w.u32(w.u32(buf) + 4*i))
		if w.act15(w.u32(m+0xc)) || w.u8(0x683f94) == 0 && w.u32(w.u32(m+0xc)+0x74) != 0 ||
			w.u8(m+0x16) != 1 || w.stub(0x434b60, 0, 0, 1)&0xff == 0 || w.u32(m+0x2fd) > 1 {
			continue
		}
		if w.u32(m+0x87) != 0 || w.u32(m+0x107) >= 0xf {
			w.release(m, 0)
			continue
		}
		eff := w.u32(inst + 0xc8)
		k := w.call(0x552410, 0, eff)
		var resisted bool
		if w.real {
			t := w.template(m)
			resisted = monsterMentalResistRollNode([]int64{int64(int32(eff)), int64(w.u8(t + 0xcb)),
				int64(w.u32(m + 0x107)), int64(w.u8(t + 0x24f)), int64(w.u8(t + 0x17a)), int64(int8(w.u8(m + 0x21b)))}, w.r)[0] != 0
		} else {
			resisted = w.replay(0x552410, k)&0xff != 0
		}
		mode := uint32(1)
		if resisted {
			mode = 2
		}
		if w.u8(0x683f94) != 0 {
			w.release(m, mode)
		} else {
			w.releaseGroup(w.group(w.u32(m+4)), mode)
		}
		if !resisted {
			w.put8(inst+0x125, 1)
		}
	}
}

// releaseGroup is 0x5117d0(g, mode): every member not in actor state 0x15.
func (w *spcWorld) releaseGroup(g, mode uint32) {
	l := w.u32(g + 8)
	for i := uint32(0); i < w.listCount(l); i++ {
		if m := w.findMonster(w.listAt(l, i)); !w.act15(w.u32(m + 0xc)) {
			w.release(m, mode)
		}
	}
}

// reflectBest is 0x54c930(inst): a reflection shield turns the spell around.
func (w *spcWorld) reflectBest(inst uint32) {
	spell := w.u32(inst)
	if !w.mstSpellFits(spell) || w.u8(inst+0x76) != 0 || w.u8(inst+0x78) != 0 || w.u8(inst+0x77) != 0 {
		return
	}
	var best, bc, bm uint32
	if int32(w.u32(inst+0xf4)) > 6 || int32(w.u32(inst+0xe4)) > 6 {
		spcPanic("reflection target list past the fixture's 6 ids")
	}
	for i := uint32(0); int32(i) < int32(w.u32(inst+0xf4)); i++ {
		if int32(i) >= int32(w.u32(inst+0xf4)) {
			spcPanic("0x54c9a0: list index past its count")
		}
		c := w.charBase(w.u32(w.u32(inst+0xfc) + 4*i))
		if w.u32(c+0xb01) < 0x12 && w.u32(c+0xa9d) != 0 && w.u32(c+0xa95) > best {
			best, bc = w.u32(c+0xa95), c
		}
	}
	for i := uint32(0); int32(i) < int32(w.u32(inst+0xe4)); {
		if int32(i) >= int32(w.u32(inst+0xe4)) {
			spcPanic("0x54ca0e: list index past its count")
		}
		d := w.u32(inst + 0xec)
		h, ok := w.monsterHandle(w.u32(d + 4*i))
		if !ok {
			n := w.u32(inst + 0xe4)
			for j := i; j+1 < n; j++ {
				w.put32(d+4*j, w.u32(d+4*j+4))
			}
			w.put32(inst+0xe4, n-1)
			continue
		}
		m := w.monsterRecord(h)
		if m == 0 {
			spcPanic("0x54ca76 asserts: monster handle without a record")
		}
		if w.u32(m+0x107) < 0x12 && w.u32(m+0xdf) != 0 && w.u32(m+0xd7) > best {
			best, bm, bc = w.u32(m+0xd7), m, 0
		}
		i++
	}
	if best == 0 {
		return
	}
	w.put32(inst+0xd0, min(w.u32(inst+0xd0), best))
	s, t := w.local(0x34), w.local(0x20)
	w.copyDw(s, inst+0x5c, 13)
	w.copyDw(t, inst+0x90, 8)
	w.reflect(spell, s, t)
	w.put8(s+0x1b, 1)
	w.cast(spell, s, t, w.u32(inst+0xd0), w.u32(inst+0xd4), 0, 0, 0, 0, 0, 0)
	if bc != 0 {
		if w.u8(bc+4) == 0 {
			spcPanic("0x517ec0 asserts: reflecting character slot not in use")
		}
		idx := (bc - w.u32(0x685174)) / mstCharStride
		w.notice(idx)
		w.put32(bc+0xa95, w.u32(bc+0xa95)-1)
		if w.u32(bc+0xa95) == 0 {
			w.stub(0x523a80, idx, 4) // character_effect_remove (D4): eax and writes unread here
		}
		return
	}
	w.stub(0x590b40, bm, w.u32(w.u32(0x68c09c)+0x660))
	w.put32(bm+0xd7, w.u32(bm+0xd7)-1)
	if w.u32(bm+0xd7) == 0 { // 0x524390(id, 4): clear buff slot 4, 0x4acd80, rebuild
		id := w.u32(bm)
		m := w.findMonster(id)
		for _, o := range []uint32{0xd7, 0xdb, 0xdf} {
			w.put32(m+o, 0)
		}
		w.stub(0x4acd80, w.u32(m+0xc), 0x14, 0)
		w.rebuild(id)
	}
}

func spcBody(w *mcaWorld) {
	s := &spcWorld{mcaWorld: w}
	w.tab = spcStubs
	s.put(mstRet, 4, uint64(s.cast(s.arg(0), s.arg(1), s.arg(2), s.arg(3), s.arg(4), s.arg(5), s.arg(6), s.arg(7), s.arg(8), s.arg(9), s.arg(10))))
}

// stub shadows mcaWorld.stub for every member body: Emu replays the case stub;
// F runs the real callee node (marCall, as marD4 in n_53e250.go) for the D4
// callees whose return or writes this group reads back (spcCallees). 0x437f30
// (spawn_position_grid, placement) stays a case input in F too (MG 2026-10-11
// numeric-only scope).
func (w *spcWorld) stub(a uint32, args ...uint32) uint32 {
	k := w.call(a, args...)
	if c := spcCallees[a]; w.real && c != nil {
		if a == 0x4fd030 {
			// Relocate the callee's list buffers and heap into this world.
			// Raw callee arena pointers cannot be used by a recursive caller.
			var data [2]uint32
			for i, list := range args[4:6] {
				data[i] = w.alloc(8 * 4)
				w.copyDw(data[i], w.u32(list+12), w.u32(list+4))
				w.put32(list+12, data[i])
			}
			heap := w.alloc(64 * 4)
			mapped := *c
			mapped.out = append([]marLoc(nil), c.out...)
			for i, f := range mapped.out {
				if f.obj == -1 && f.off >= mstHeap && f.off < mstHeap+64*4 {
					mapped.out[i].off = heap + f.off - mstHeap
				}
			}
			ret := marCall(w.mcaWorld, &mapped, args)
			for i, list := range args[4:6] {
				ptr := w.u32(list + 12)
				if ptr >= mstHeap && ptr < mstHeap+64*4 {
					ptr = heap + ptr - mstHeap
				} else if ptr == 0x20000100+uint32(i)*0x40 {
					ptr = data[i]
				} else {
					spcPanic("area target list pointer outside callee fixture")
				}
				w.put32(list+12, ptr)
			}
			return ret
		}
		return marCall(w.mcaWorld, c, args)
	}
	return w.replay(a, k, args...)
}

func spellFailureBackfireAndEffectNode(in []int64, r Rand) []int64 {
	return mcaRun(&spcSpec, true, spcBody)(in, r)
}

func spcEmu(in []int64, r Rand) []int64 { return mcaRun(&spcSpec, false, spcBody)(in, r) }

func init() {
	Nodes["004fb4c0"] = Node{Addr: "004fb4c0", In: spcIn, Out: spcOut, F: spellFailureBackfireAndEffectNode, Emu: spcEmu}
}

